// truncateString truncates a string to the specified length, adding "..." if truncated.
func strategy.TruncateDescription(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	if maxLen <= 3 {
		return s[:maxLen]
	}
	return s[:maxLen-3] + "..."
}

